export class ExpiryDate {
  private constructor(private readonly month: number, private readonly year: number) {}

  static create(value: string): ExpiryDate {
    const match = /^(0[1-9]|1[0-2])\/(\d{2})$/.exec(value);
    if (!match) {
      throw new InvalidExpiryDateError();
    }
    const month = parseInt(match[1]);
    const year = 2000 + parseInt(match[2]);
    return new ExpiryDate(month, year);
  }

  isExpired(): boolean {
    const expiryDate = new Date(this.year, this.month - 1);
    return expiryDate < new Date();
  }
